command:
// ==========================================
// LUNAS WIRKUNG: HUSTEN UND JUCKEN (APHASMA)
//
// - mehrere Targets
// - Reichweite: 4 Schritt
// - nur Menschen: creature + Spezies Mensch
// - gültige Ziele Erfolg, ungültige Misserfolg
// - gespeicherte Ziele ohne erneutes Target
// - vier FW-Modifikatoren mit Modus 2
// - Wert: −QS
// - Dauer: QS × 2 Minuten
// - Effektanlage über Block 6
// - Wirkungsende über Block 7
// - eine Karte + roter GM-Button über Block 11
// ==========================================

(async function () {
const macroUuid = this?.uuid || null;

// +++ 1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++++++

const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
const frameworkFehlt = !globalThis.DSK?.Effekt?.Anwenden || !globalThis.DSK?.EffektEnde?.Register ||
    !globalThis.DSK?.QS?.Ermitteln || !globalThis.DSK?.Token?.Finde ||
    !globalThis.DSK?.Target?.Merken || !globalThis.DSK?.Target?.Finden || !globalThis.DSK?.Target?.Actor ||
    !globalThis.DSK?.Geometrie?.Distanz ||
    !globalThis.DSK?.GMAnfrage?.Speichern || !globalThis.DSK?.GMAnfrage?.Finden ||
    !globalThis.DSK?.GMAnfrage?.Lesen || !globalThis.DSK?.GMAnfrage?.Loeschen ||
    !globalThis.DSK?.GabenUI?.GMMakroButton ||
    !globalThis.DSK?.GabenUI?.AnfrageKarteErstellen ||
    !globalThis.DSK?.GabenUI?.AnfrageKarteAktualisieren;

if (frameworkFehlt) {
    const fwMacro = await fromUuid(frameworkUuid);
    if (!fwMacro?.execute) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!");
    await fwMacro.execute();
    await new Promise(resolve => setTimeout(resolve, 150));
}

const DSK_FW = globalThis.DSK;
if (!DSK_FW?.Effekt?.Anwenden || !DSK_FW?.EffektEnde?.Register ||
    !DSK_FW?.QS?.Ermitteln || !DSK_FW?.Token?.Finde ||
    !DSK_FW?.Target?.Merken || !DSK_FW?.Target?.Finden || !DSK_FW?.Target?.Actor ||
    !DSK_FW?.Geometrie?.Distanz ||
    !DSK_FW?.GMAnfrage?.Speichern || !DSK_FW?.GMAnfrage?.Finden ||
    !DSK_FW?.GMAnfrage?.Lesen || !DSK_FW?.GMAnfrage?.Loeschen ||
    !DSK_FW?.GabenUI?.GMMakroButton ||
    !DSK_FW?.GabenUI?.AnfrageKarteErstellen ||
    !DSK_FW?.GabenUI?.AnfrageKarteAktualisieren
) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework 01.02 wurde nicht vollständig geladen!");

// +++ 2 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++++++++

const gabenName = "Husten und Jucken", vollerName = "Husten und Jucken (Aphasma)", ahne = "Aphasma";
const endeKey = "hustenUndJuckenAphasma", flagKey = "pendingHustenUndJuckenAphasma";
const maxReichweite = 4;
const endeText = "Die magische Katzenhaarallergie klingt ab. Das Niesen hört auf und das Ziel kann wieder frei atmen.";
const fwModifikatoren = [
    "system.skillModifiers.skill.FW",
    "system.skillModifiers.ahnengabe.FW",
    "system.skillModifiers.feature.FW",
    "system.skillModifiers.FW"
];

DSK_FW.EffektEnde.Register(endeKey, vollerName, endeText);

// +++ 3 - GABENSPEZIFISCHE HELFER +++++++++++++++++++++++++++++

const speciesVon = actor => String(
    actor?.system?.species?.value ||
    actor?.system?.details?.species?.value ||
    actor?.system?.details?.species || ""
).trim();

const istMensch = actor =>
    String(actor?.type || "").toLowerCase() === "creature" &&
    speciesVon(actor).toLowerCase().includes("mensch");

const liesSpezies = actor => speciesVon(actor) || "Unbekannt";

const ermittleSymptome = qs => {
    let symptome = ["gerötete Augen", "juckende Nase"];
    if (qs >= 2) symptome.push("laufende Nase", "starker Niesreiz");
    if (qs >= 3) symptome.push("Atemschwierigkeiten");
    if (qs >= 4) symptome.push("starker Juckreiz");
    if (qs >= 5) symptome.push("Ausschlag");
    if (qs >= 6) symptome = [...symptome.filter(symptom => symptom !== "Ausschlag"), "starker Ausschlag mit roten Pusteln"];
    return symptome.join(", ");
};

const raeumeQSAuf = async actor => {
    if (actor?.getFlag("world", "letzteGabenQS") !== undefined) await actor.unsetFlag("world", "letzteGabenQS");
    if (actor?.getFlag("world", "letzteGabenMessageId") !== undefined) await actor.unsetFlag("world", "letzteGabenMessageId");
};

const ladeGespeichertesZiel = async daten => {
    if (!daten) return { token: null, actor: null };
    const token = await DSK_FW.Target.Finden(daten);
    return { token, actor: token?.actor || await DSK_FW.Target.Actor(daten) };
};

const wirkungsBeschreibung = (qs, symptomText) =>
    `Das Ziel wird von den Symptomen einer heftigen magischen Katzenhaarallergie übermannt.` +
    `<br><br><b>Symptome:</b> ${symptomText}` +
    `<br><b>Abzug:</b> −${qs} auf alle Proben` +
    `<br><b>Zielkategorie:</b> Mensch` +
    `<br><b>Reichweite:</b> ${maxReichweite} Schritt`;

// +++ 4 - EFFEKT ÜBER BLOCK 6 ++++++++++++++++++++++++++++++++

const wendeEffektAn = async ({ casterActor, targetActor, qs, symptomText }) => {
    if (!casterActor || !targetActor || !istMensch(targetActor)) return false;

    const alteEffekte = targetActor.effects.filter(effect =>
        (effect.name || effect.label || "") === vollerName &&
        effect.getFlag("dsk", "casterUuid") === casterActor.uuid
    );

    if (alteEffekte.length) {
        await targetActor.deleteEmbeddedDocuments("ActiveEffect", alteEffekte.map(effect => effect.id));
    }

    const dauerMinuten = qs * 2;
    const beschreibung =
        `Das Ziel leidet unter einer heftigen magischen Katzenhaarallergie.` +
        `<br><br><b>Symptome:</b> ${symptomText}` +
        `<br><b>Abzug:</b> −${qs} auf alle Proben` +
        `<br><br><b>Wirkungsdauer:</b> ${dauerMinuten} Minuten`;

    const effekt = await DSK_FW.Effekt.Anwenden({
        name: vollerName, ahne, beschreibung, gabeZiel: "mensch",
        qs, skills: fwModifikatoren, key: "direkterSystemwert", formel: "-qs",
        ziel: targetActor,
        duration: { seconds: dauerMinuten * 60, startTime: game.time.worldTime },
        showIcon: 1,
        flags: { dsk: {
            isHustenUndJucken: true, casterUuid: casterActor.uuid, qs,
            value: qs, max: 6, symptome: symptomText,
            wirkungsende: {
                sfName: endeKey, basisEffektName: vollerName,
                beschreibungFuerEnde: endeText
            }
        }}
    });

    if (!effekt) return false;

    const endeDaten = effekt.getFlag("dsk", "wirkungsende");
    const erwarteterWert = -qs;
    const korrekteChanges = fwModifikatoren.every(key =>
        (effekt.changes || []).some(change =>
            change.key === key &&
            Number(change.mode) === 2 &&
            Number(change.value) === erwarteterWert
        )
    );

    return (
        (effekt.name || effekt.label || "") === vollerName &&
        effekt.getFlag("dsk", "isHustenUndJucken") === true &&
        effekt.getFlag("dsk", "casterUuid") === casterActor.uuid &&
        Number(effekt.getFlag("dsk", "qs")) === qs &&
        Number(effekt.getFlag("dsk", "value")) === qs &&
        Number(effekt.getFlag("dsk", "max")) === 6 &&
        effekt.getFlag("dsk", "symptome") === symptomText &&
        endeDaten?.sfName === endeKey &&
        endeDaten?.basisEffektName === vollerName &&
        endeDaten?.beschreibungFuerEnde === endeText &&
        korrekteChanges
    );
};

// +++ 5 - GM-ANFRAGE VERARBEITEN +++++++++++++++++++++++++++++

const verarbeiteAnfrage = async (casterActor, daten) => {
    if (!game.user.isGM || !casterActor || !daten) return false;

    if (daten.casterUuid && daten.casterUuid !== casterActor.uuid) {
        ui.notifications.warn("Luna sagt 🌙: Die gespeicherte Anfrage passt nicht zum Wirkenden.");
        return false;
    }

    if (daten.sceneId && daten.sceneId !== canvas.scene?.id) {
        ui.notifications.warn(`Luna sagt 🌙: Die Anfrage von „${casterActor.name}“ gehört zu einer anderen Szene.`);
        return false;
    }

    const casterToken = DSK_FW.Token.Finde(casterActor, daten.casterTokenId, daten.casterTokenUuid);
    if (!casterToken) {
        ui.notifications.warn(`Luna sagt 🌙: Der Token von „${casterActor.name}“ wurde nicht gefunden!`);
        return false;
    }

    const qs = Math.max(1, Math.floor(Number(daten.qs) || 1));
    const symptomText = daten.symptomText || ermittleSymptome(qs);
    const casterName = daten.casterName || DSK_FW.ResolveTokenName(casterActor);
    const erfolge = [], misserfolge = foundry.utils.deepClone(daten.misserfolge || []);

    for (const zielDaten of daten.ziele || []) {
        const { actor: targetActor } = await ladeGespeichertesZiel(zielDaten);
        const targetName = zielDaten.name || targetActor?.name || "Unbekanntes Ziel";

        if (!targetActor) {
            misserfolge.push({ name: targetName, grund: "Zielakteur wurde nicht gefunden" });
            continue;
        }

        if (!istMensch(targetActor)) {
            misserfolge.push({ name: targetName, grund: `Kein Mensch (${liesSpezies(targetActor)})` });
            continue;
        }

        try {
            const erfolgreich = await wendeEffektAn({ casterActor, targetActor, qs, symptomText });
            if (erfolgreich) erfolge.push({ name: targetName, rolle: "Betroffenes Ziel" });
            else misserfolge.push({ name: targetName, grund: "Effekt konnte nicht vollständig angelegt werden" });
        } catch (error) {
            console.error("Husten und Jucken: Effektanlage fehlgeschlagen.", { targetActor, error });
            misserfolge.push({ name: targetName, grund: "Effektanlage fehlgeschlagen" });
        }
    }

    const erfolgreich = erfolge.length > 0;

    await DSK_FW.GabenUI.AnfrageKarteAktualisieren({
        messageId: daten.messageId, gabenName: vollerName, ahne,
        beschreibung: daten.beschreibung || wirkungsBeschreibung(qs, symptomText),
        wirkender: casterName, ziele: erfolge, misserfolge,
        dauerText: `${qs * 2} Minuten`, erfolgreich
    });

    if (erfolgreich) ui.notifications.info(`Luna sagt 🌙: Husten und Jucken wurde auf ${erfolge.length} Ziel(e) angewendet.`);
    else ui.notifications.error("Luna sagt 🌙: Husten und Jucken konnte auf kein Ziel angewendet werden.");

    return true;
};

// +++ 6 - GM-MODUS ++++++++++++++++++++++++++++++++++++++++++++

if (game.user.isGM) {
    const anfragen = DSK_FW.GMAnfrage.Finden(flagKey);

    if (anfragen.length) {
        for (const anfrageActor of anfragen) {
            const daten = DSK_FW.GMAnfrage.Lesen(anfrageActor, flagKey);
            if (!daten) continue;

            if (await verarbeiteAnfrage(anfrageActor, daten)) {
                await DSK_FW.GMAnfrage.Loeschen(anfrageActor, flagKey);
            }
        }
        return;
    }
}

// +++ 7 - WIRKENDER UND QS ++++++++++++++++++++++++++++++++++++

let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character || null;

if (!casterActor) {
    casterActor =
        canvas.tokens.placeables.map(token => token.actor)
            .find(actor => actor?.getFlag("world", "letzteGabenQS") !== undefined) ||
        game.actors.find(actor => actor.getFlag("world", "letzteGabenQS") !== undefined) || null;
}

if (!casterActor) return ui.notifications.warn("Luna sagt 🌙: Kein Akteur gefunden! Bitte wähle deinen Token aus.");
if (!game.user.isGM && !casterActor.isOwner) return ui.notifications.warn("Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!");

const casterToken = DSK_FW.Token.Finde(casterActor);
if (!casterToken) return ui.notifications.warn("Luna sagt 🌙: Das Token des Wirkenden wurde nicht gefunden!");

const casterName = DSK_FW.ResolveTokenName(casterActor);
const qs = DSK_FW.QS.Ermitteln({
    actor: casterActor, gabenName,
    suchbegriffe: ["Husten und Jucken Probe", "Husten und Jucken"],
    testDataObj: typeof testData !== "undefined" ? testData : null,
    fallback: 0, protokollieren: true
});

if (qs <= 0) {
    await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName, ahne,
        beschreibung: "Die magische Katzenhaarallergie konnte nicht ausgelöst werden.",
        wirkender: casterName, ziele: [],
        misserfolge: [{ name: casterName, grund: "Probe fehlgeschlagen" }],
        dauerText: "0 Minuten", gmBereich: false,
        angewendet: true, erfolgreich: false,
        anfragenderUserId: game.user.id
    });

    await raeumeQSAuf(casterActor);
    return;
}

// +++ 8 - TARGETS PRÜFEN ++++++++++++++++++++++++++++++++++++++

const targets = Array.from(game.user.targets || []);
if (!targets.length) {
    await raeumeQSAuf(casterActor);
    return ui.notifications.warn("Luna sagt 🌙: Bitte wähle mindestens ein Ziel per Target aus!");
}

const gueltigeZiele = [], misserfolge = [];

for (const targetToken of targets) {
    const targetActor = targetToken?.actor;
    const targetName = targetToken?.name || targetActor?.name || "Unbekanntes Target";

    if (!targetActor) {
        misserfolge.push({ name: targetName, grund: "Kein gültiger Akteur" });
        continue;
    }

    if (targetActor.uuid === casterActor.uuid || targetActor.id === casterActor.id) {
        misserfolge.push({ name: targetName, grund: "Der Wirkende kann nicht selbst Ziel sein" });
        continue;
    }

    const distanz = DSK_FW.Geometrie.Distanz(casterToken, targetToken);
    if (distanz > maxReichweite) {
        misserfolge.push({ name: targetName, grund: `${Math.ceil(distanz - maxReichweite)} Schritt zu weit entfernt` });
        continue;
    }

    if (!istMensch(targetActor)) {
        misserfolge.push({ name: targetName, grund: `Kein Mensch (${liesSpezies(targetActor)})` });
        continue;
    }

    const zielDaten = DSK_FW.Target.Merken(targetToken);
    if (!zielDaten) {
        misserfolge.push({ name: targetName, grund: "Ziel konnte nicht gespeichert werden" });
        continue;
    }

    gueltigeZiele.push(zielDaten);
}

// +++ 9 - KEIN GÜLTIGES ZIEL ++++++++++++++++++++++++++++++++++

const symptomText = ermittleSymptome(qs);
const beschreibung = wirkungsBeschreibung(qs, symptomText);
const dauerText = `${qs * 2} Minuten`;

if (!gueltigeZiele.length) {
    await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName, ahne, beschreibung, wirkender: casterName,
        ziele: [], misserfolge, dauerText,
        gmBereich: false, angewendet: true, erfolgreich: false,
        anfragenderUserId: game.user.id
    });

    await ChatMessage.create({
        speaker: { alias: "System" },
        whisper: [game.user.id],
        content: `${DSK_FW.UI.Header(vollerName, DSK_FW.Symbol(ahne))}
            <div class="dskbox2" style="margin-top:10px;text-align:center;">
                <p><b>Kontrolliere deine Target-Auswahl.</b></p>
                <p>Wirke die Gabe erneut, wenn es der GM erlaubt; ansonsten ist dies ein Fehlschlag.</p>
            </div>`
    });

    await raeumeQSAuf(casterActor);
    return;
}

// +++ 10 - GEMEINSAME KARTE + GM-ANFRAGE ++++++++++++++++++++++

const gmLink = DSK_FW.GabenUI.GMMakroButton(
    macroUuid, "Effekt anwenden",
    "Das Makro muss durch die Spielleitung ausgeführt werden."
);

const nachricht = await DSK_FW.GabenUI.AnfrageKarteErstellen({
    gabenName: vollerName, ahne, beschreibung, wirkender: casterName,
    ziele: gueltigeZiele.map(ziel => ({ name: ziel.name, rolle: "Betroffenes Ziel" })),
    misserfolge, dauerText,
    gmLink, gmBereich: !game.user.isGM,
    anfragenderUserId: game.user.id
});

if (!nachricht) {
    await raeumeQSAuf(casterActor);
    return ui.notifications.error("Luna sagt 🌙: Die Wirkungskarte konnte nicht erstellt werden!");
}

const anfrageDaten = {
    casterUuid: casterActor.uuid, casterName,
    casterTokenId: casterToken.id,
    casterTokenUuid: casterToken.document?.uuid || casterToken.uuid || null,
    qs, symptomText, ziele: gueltigeZiele, misserfolge, beschreibung,
    sceneId: canvas.scene?.id || null,
    requestedByUserId: game.user.id,
    messageId: nachricht.id, macroUuid, erstellt: Date.now()
};

if (game.user.isGM) {
    await verarbeiteAnfrage(casterActor, anfrageDaten);
    await raeumeQSAuf(casterActor);
    return;
}

await DSK_FW.GMAnfrage.Speichern(casterActor, flagKey, anfrageDaten);
await raeumeQSAuf(casterActor);
ui.notifications.info("Luna sagt 🌙: Husten und Jucken wurde bei der Spielleitung zur Anwendung beantragt.");

}).call(this);
